def rotate_half(x):
    """Rotates the second half to the first: [-x2, x1] for each pair."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat([-x2, x1], dim=-1)

def apply_rope(q, cos, sin):
    return q * cos + rotate_half(q) * sin
